#include <stdio.h>

struct Cat {
    char name[20];
    int fish;
};

void feed(struct Cat *c, int n) {
    c->fish = c->fish + n;
}

int main(void) {
    struct Cat a = {"小橘", 2};

    printf("%s 吃了 %d 条喵\n", a.name, a.fish);
    feed(&a, 3);
    printf("喂过之后 %s 吃了 %d 条喵\n", a.name, a.fish);
    return 0;
}

