#include <stdio.h>
#include <stdlib.h>
#include <string.h>

struct Cat {
    char name[20];
    int fish;
};

int main(void) {
    struct Cat *p = (struct Cat *)malloc(sizeof(struct Cat));

    if (p == NULL) {
        printf("仓库没租到喵\n");
        return 0;
    }

    strcpy(p->name, "小橘");
    p->fish = 3;
    printf("%s 有 %d 条喵\n", p->name, p->fish);

    free(p);
    p = NULL;
    return 0;
}

